#include <algorithm>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <limits>
#include <set>
#include <tuple>
#include <vector>
__extension__ using Wide=unsigned __int128;
struct Point{std::int32_t x,y;std::size_t index;};
static Wide sq(std::int64_t x){const auto m=static_cast<std::uint64_t>(x<0?-x:x);return Wide(m)*m;}
static Wide distance(const Point&a,const Point&b){return sq(std::int64_t(a.x)-b.x)+sq(std::int64_t(a.y)-b.y);}
static std::uint64_t radius(Wide best){
 if(best>std::numeric_limits<std::uint64_t>::max())return std::numeric_limits<std::uint32_t>::max();
 auto r=std::min<std::uint64_t>(static_cast<std::uint64_t>(std::sqrt(static_cast<long double>(best))),std::numeric_limits<std::uint32_t>::max());
 while(r&&Wide(r)*r>=best)--r;while(r<std::numeric_limits<std::uint32_t>::max()&&Wide(r+1)*(r+1)<best)++r;return r;
}
int main(){std::ios::sync_with_stdio(false);std::cin.tie(nullptr);int tests{};std::cin>>tests;while(tests--){
 std::size_t n{};std::cin>>n;std::vector<Point>p(n);for(std::size_t i=0;i<n;++i){std::cin>>p[i].x>>p[i].y;p[i].index=i;}
 std::sort(p.begin(),p.end(),[](const Point&a,const Point&b){return a.x!=b.x?a.x<b.x:a.y<b.y;});Wide best=distance(p[0],p[1]);std::size_t a=p[0].index,b=p[1].index,left=0;
 using Key=std::tuple<std::int64_t,std::int64_t,std::size_t>;std::set<Key> active;
 for(std::size_t i=0;i<n&&best;++i){
  while(left<i&&sq(std::int64_t(p[i].x)-p[left].x)>=best){active.erase(Key{p[left].y,p[left].x,p[left].index});++left;}
  const auto r=static_cast<std::int64_t>(radius(best));const auto low=std::int64_t(p[i].y)-r,high=std::int64_t(p[i].y)+r;
  for(auto it=active.lower_bound(Key{low,std::numeric_limits<std::int64_t>::min(),0});it!=active.end()&&std::get<0>(*it)<=high;++it){
   const auto[y,x,index]=*it;const Wide d=sq(std::int64_t(p[i].x)-x)+sq(std::int64_t(p[i].y)-y);if(d<best){best=d;a=index;b=p[i].index;}
  }
  active.emplace(p[i].y,p[i].x,p[i].index);
 }
 if(a>b)std::swap(a,b);std::cout<<a<<' '<<b<<'\n';
}}

